a.AUTHOR_AGENT='/root/finite_grade5'
def create(node,specs,hints):
 if (a.R/('authored_batches/finish_g5_'+node+'.jsonl')).exists():
  print('SKIP_OWN_EXISTING_BATCH',node);return
 return a.make('old_g5_'+node,'finish_g5_'+node,specs,hints)

