create('altitude_circle_drawing',[
C('acute_altitude_plan','Trong mô hình tam giác nhọn ABC, chọn BC làm đáy. Hãy lập quy trình dùng ê ke và thước để vẽ đường cao từ A; chưa có hình vẽ thật để xác nhận thao tác.', [('Tam giác ABC nhọn, đáy BC',None,'')],'Mô tả quy trình dựng và cách kiểm đường cao.',[
S('Định hướng ê ke','Đường cao từ đỉnh phải vuông góc với đường thẳng chứa đáy đối diện.','Đặt một cạnh góc vuông ê ke dọc BC, dịch đến khi cạnh góc vuông kia đi qua A','Đây là kế hoạch dụng cụ; giữ ê ke không xoay sai hướng khi dịch.'),S('Vạch và kiểm','Nối A đến điểm H trên BC theo cạnh ê ke qua A.','AH là đoạn dự kiến cần vẽ, H trên BC và AH vuông góc BC','Kiểm góc tại H bằng góc vuông ê ke, đỉnh A nằm trên đoạn và chân H thuộc đáy. Chưa khẳng định bản vẽ thực tế đạt.')],[('Quy trình','Dự kiến kẻ AH qua A vuông góc BC, H trên BC rồi kiểm bằng ê ke','')]),
C('obtuse_external_foot','Bản dựng giả định tam giác ABC có đáy BC nằm ngang. Từ A hạ vuông góc đường thẳng BC tại H, H nằm ngoài đoạn BC về phía B. Em cần vẽ đường cao theo đáy BC. Nêu cách thể hiện và kiểm, không chuyển H vào trong đoạn cho đẹp.', [('H trên phần kéo dài qua B, AH vuông góc BC',None,'')],'Mô tả đường cao có chân ngoài đoạn đáy.',[
S('Dùng đường thẳng chứa đáy','Đường cao vuông góc với đường thẳng chứa cạnh đáy, chân không bắt buộc trong đoạn.','Kéo dài BC qua B và giữ chân H đã cho trên phần kéo dài','Kiểm A,H thẳng hàng theo đoạn vuông góc và H thuộc đường thẳng BC; không thay hình chỉ vì chân ở ngoài.'),S('Kẻ đoạn cần vẽ','Đường cao bắt đầu từ đỉnh đối diện đáy.','Kẻ đoạn AH và đánh dấu góc vuông tại H trong bản dựng dự kiến','Chỉ là quy trình từ mô tả đầy đủ, chưa đánh giá nét vẽ thật.')],[('Đường cần vẽ','AH với chân H trên phần kéo dài BC','')]),
C('circle_compass_plan','Lập kế hoạch vẽ đường tròn tâm O bán kính 2,5 cm bằng compa và thước. Tờ giấy giả định đủ rộng; chưa có ảnh bản vẽ hoặc thao tác thật.', [('Bán kính yêu cầu','2.5','cm'),('Tâm O đã chọn',None,'')],'Mô tả quy trình vẽ và cách kiểm bán kính.',[
S('Đặt độ mở','Khoảng cách từ tâm tới mọi điểm đường tròn phải bằng bán kính yêu cầu.','Dùng thước mở hai mũi compa cách nhau 2,5 cm','Đặt mũi nhọn tại O; không lấy 2,5 cm làm đường kính.'),S('Vẽ và kiểm dự kiến','Giữ tâm và độ mở không đổi khi quay.','Quay một vòng rồi đo khoảng cách từ O đến vài điểm trên nét tròn để kiểm độ mở','Phép kiểm vài điểm hỗ trợ kiểm thao tác, không là chứng minh mọi điểm bản vẽ thật chính xác; chưa có bản vẽ để nghiệm thu.')],[('Quy trình','Giữ mũi tại O, độ mở bằng bán kính yêu cầu, quay và kiểm khoảng cách tới tâm','')]),
C('median_not_automatically_altitude','Mô tả đã xác nhận: D là trung điểm BC nhưng AD không vuông góc BC. Em viết: "D là trung điểm nên AD là đường cao từ A". Hãy nhận xét, không có ảnh khác.', [('D trung điểm, AD không vuông góc BC',None,'')],'Nhận xét điều kiện đường cao từ mô tả.',[
S('Kiểm điều kiện vuông góc','Đi qua trung điểm chưa thay thế điều kiện vuông góc với đáy.','AD không là đường cao theo mô tả','Chính đề đã xác nhận AD không vuông góc BC; cần kẻ từ A đoạn vuông góc đường thẳng BC. Không đoán độ dài hay hình dáng từ ảnh chưa có.')],[('Kết luận','AD không là đường cao theo mô tả','')],student='D là trung điểm nên AD là đường cao từ A',kind='misconception'),
C('missing_drawing_and_scale','Em yêu cầu xác nhận bản vẽ đường tròn bán kính 3 cm và đường cao đã đúng chưa, nhưng không gửi bản vẽ, tâm, đáy được chọn, thước chuẩn hay mô tả thao tác.', [('Yêu cầu kiểm nhưng chưa có bản vẽ',None,'')],'Hỏi bằng chứng cần để kiểm bản vẽ.',[],[],kind='guard',hints=H('Chưa có hình và dấu mốc để kiểm nét vẽ.','Cần ảnh rõ tâm, bán kính có thước hoặc tỉ lệ, tam giác và đáy chọn cùng dấu góc vuông.','Chỉ hướng dẫn cách kiểm dự kiến, chưa xác nhận thao tác thực tế khi thiếu bằng chứng.'))
],H('Xác định điểm cố định và quan hệ cần giữ khi dựng bằng dụng cụ.','Với đường cao kiểm vuông góc đường thẳng chứa đáy; với đường tròn giữ khoảng cách tới tâm không đổi.','Nêu cách kiểm bằng ê ke, thước hoặc compa; kế hoạch chưa chứng nhận bản vẽ hay thao tác thật.'))
